To write a C++ function that converts Markdown formatted text to HTML, you can use a third-party library like `cppmarkdown`. Here's a simple example of how you can achieve this:

```cpp
#include <iostream>
#include <string>
#include <cppmarkdown/Markdown.h>

std::string markdownToHtml(const std::string& markdownText) {
    markdown::Markdown markdown;
    std::string htmlText = markdown.convert(markdownText);
    return htmlText;
}

int main() {
    std::string markdownText = "# Hello, World!\nThis is a sample text.";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "Markdown Text: " << markdownText << std::endl;
    std::cout << "HTML Text: " << htmlText << std::endl;
    return 0;
}
```

